// Writes the precache list and cache version into `sw.js` (the block between
// the "Generated by scripts/build-sw.js" markers). Deterministic: same files,
// byte-identical `sw.js`. Zero dependencies.
//
// Usage (from the repo root), after changing any file the app serves:
//   node scripts/build-sw.js
//
// The list is every file under `APP_DIRS` plus `APP_FILES`, skipping
// dotfiles. `CACHE_VERSION` is the first `VERSION_LENGTH` hex digits of a
// SHA-256 over every listed path and its bytes, so a change to any precached
// file (or adding, removing or renaming one) gives a new cache name. `sw.js`
// itself is not precached (browsers fetch it themselves to check for
// updates), so it is not hashed either. test/sw.test.js fails if the
// committed block differs from a fresh build.

import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SW_PATH = join(REPO_ROOT, 'sw.js');

/** Top-level files the app serves. */
export const APP_FILES = Object.freeze(['index.html', 'manifest.webmanifest']);

/** Directories whose every (non-dot) file the app serves. */
export const APP_DIRS = Object.freeze(['css', 'data', 'flags', 'icons', 'js']);

/** Hex digits of the content hash kept as `CACHE_VERSION`. */
export const VERSION_LENGTH = 16;

export const BLOCK_START = '// ---- Generated by scripts/build-sw.js: do not edit by hand ----';
export const BLOCK_END = '// ---- End of generated block ----';

function walkFiles(root, relativeDir) {
  const entries = readdirSync(join(root, relativeDir), { withFileTypes: true });
  return entries
    .filter((entry) => !entry.name.startsWith('.'))
    .flatMap((entry) => {
      const relativePath = `${relativeDir}/${entry.name}`;
      if (entry.isDirectory()) {
        return walkFiles(root, relativePath);
      }
      return entry.isFile() ? [relativePath] : [];
    });
}

/**
 * List the files to precache.
 *
 * @param {string} [root=REPO_ROOT] Repo root.
 * @returns {string[]} Paths relative to `root` with `/` separators, sorted
 *   (code-unit order).
 */
export function listPrecacheFiles(root = REPO_ROOT) {
  if (typeof root !== 'string' || root === '') {
    throw new TypeError('`root` must be a non-empty string.');
  }
  return [...APP_FILES, ...APP_DIRS.flatMap((dir) => walkFiles(root, dir))].sort();
}

/**
 * Hash a set of files into a cache version.
 *
 * Each file contributes its path, its byte length and its bytes, in the
 * given order, so the hash also changes when a file is renamed.
 *
 * @param {{ path: string, bytes: Uint8Array }[]} files Files, in list order.
 * @returns {string} `VERSION_LENGTH` lowercase hex digits.
 */
export function hashFiles(files) {
  if (!Array.isArray(files) || files.length === 0) {
    throw new TypeError('`files` must be a non-empty array.');
  }
  const hash = createHash('sha256');
  files.forEach(({ path, bytes }, i) => {
    if (typeof path !== 'string' || path === '' || !(bytes instanceof Uint8Array)) {
      throw new TypeError(`\`files[${i}]\` must be a \`{ path, bytes }\` object.`);
    }
    hash.update(`${path}\n${bytes.length}\n`);
    hash.update(bytes);
  });
  return hash.digest('hex').slice(0, VERSION_LENGTH);
}

/**
 * Render the generated block of `sw.js`, markers included.
 *
 * @param {string} version Cache version (`hashFiles`).
 * @param {string[]} paths Precached paths relative to the repo root.
 * @returns {string} The block, ending without a newline.
 */
export function renderBlock(version, paths) {
  if (typeof version !== 'string' || !/^[0-9a-f]+$/.test(version)) {
    throw new TypeError('`version` must be a lowercase hex string.');
  }
  if (!Array.isArray(paths) || paths.length === 0) {
    throw new TypeError('`paths` must be a non-empty array.');
  }
  paths.forEach((path, i) => {
    if (typeof path !== 'string' || !/^[A-Za-z0-9._/-]+$/.test(path) || path.split('/').includes('..')) {
      throw new RangeError(`\`paths[${i}]\` must be a plain relative path (letters, digits, \`._/-\`).`);
    }
  });
  return [
    BLOCK_START,
    `const CACHE_VERSION = '${version}';`,
    'const PRECACHE_PATHS = [',
    paths.map((path) => `  './${path}'`).join(',\n'),
    '];',
    BLOCK_END
  ].join('\n');
}

/**
 * Replace the generated block in a `sw.js` source.
 *
 * @param {string} source Current `sw.js`.
 * @param {string} block Output of `renderBlock`.
 * @returns {string} The new source.
 */
export function replaceBlock(source, block) {
  if (typeof source !== 'string') {
    throw new TypeError('`source` must be a string.');
  }
  const start = source.indexOf(BLOCK_START);
  const end = source.indexOf(BLOCK_END);
  if (start === -1 || end === -1 || end < start || source.indexOf(BLOCK_START, start + 1) !== -1) {
    throw new Error('`sw.js` must contain exactly one generated block (see `BLOCK_START` / `BLOCK_END`).');
  }
  return source.slice(0, start) + block + source.slice(end + BLOCK_END.length);
}

/**
 * Build the generated block from the files on disk.
 *
 * @param {string} [root=REPO_ROOT] Repo root.
 * @returns {{ version: string, paths: string[], block: string }}
 */
export function buildFromRepo(root = REPO_ROOT) {
  const paths = listPrecacheFiles(root);
  const version = hashFiles(paths.map((path) => ({ path, bytes: readFileSync(join(root, path)) })));
  return { version, paths, block: renderBlock(version, paths) };
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  const { version, paths, block } = buildFromRepo();
  const source = readFileSync(SW_PATH, 'utf8');
  const updated = replaceBlock(source, block);
  if (updated === source) {
    console.log(`sw.js is up to date (version ${version}, ${paths.length} files).`);
  } else {
    writeFileSync(SW_PATH, updated);
    console.log(`Wrote sw.js (version ${version}, ${paths.length} files).`);
  }
}
